{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C11"],
      "claim": "Melagatran, a highly transferable analogue (0.994) containing ionizable guanidine and carboxylate groups, has an absolute oral bioavailability of only 3–7% in humans, supporting low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Argatroban, a high-transfer analogue with sulfonamide, guanidine, and carboxylate functionalities, is reported to have poor oral bioavailability in humans and is available only as an injectable product, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Aliskiren, a large polar non-peptide with multiple hydrogen-bonding groups and a transfer score of 0.9939, has a mean absolute oral bioavailability of only 2.6% in humans, supporting low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Alvimopan, a zwitterionic high-transfer analogue with carboxylic acid and amine groups, has an estimated oral bioavailability of only 6% in humans, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Epanolol, a polar beta-blocker with phenol and ether groups and a transfer score of 0.9939, shows mean oral bioavailability of 5.85% in fed volunteers, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "CDP323, a prodrug with a transfer score of 0.9932, achieved only 14% oral bioavailability compared with intravenous dosing in humans, still below the 20% threshold and supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Tegaserod, a high-transfer analogue containing a guanidine-like amidine, has an absolute oral bioavailability of approximately 10% in fasted humans, supporting low F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is an extremely large, highly polar, fully ionized peptide-like molecule. Multiple high-transfer experimental analogues with ionizable and polar groups all show oral bioavailability well below 20% (0.9–14%), and the physicochemical prior independently predicts negligible permeability. Therefore F >= 20% is not supported; predict low.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for a molecule of this exact size and class; all high-transfer analogues are much smaller small molecules.",
    "Potential active uptake or unusual absorption mechanisms are not represented in the evidence, but are highly unlikely given the query's extreme size and polarity."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

